Mesh<Point, double> result;
for (auto e = rt.edges_begin(); e != rt.edges_end(); ++e) {
    if (is_small_edge(rt, *e, threshold)) {
        std::vector<unsigned> face_vertices;
        auto c1 = rt.cell(e->first, e->second);
        auto c2 = rt.cell(e->second, e->first);
        if (c1 != nullptr && c2 != nullptr) {
            for (int i = 0; i < 4; ++i) {
                face_vertices.push_back(c1->vertex(i)->id());
                face_vertices.push_back(c2->vertex(i)->id());
            }
            std::sort(face_vertices.begin(), face_vertices.end());
            face_vertices.erase(std::unique(face_vertices.begin(), face_vertices.end()), face_vertices.end());
            double edge_length = std::sqrt(rt.segment(*e).squared_length());
            result.push_back(face_vertices, edge_length);
        }
    }
}
return result;

